// Estudiar (Texto | Estudiar) del bloque 6b, grupo 6I · El hígado que se envenena (Marino, caps. 52-53):
// mt-paracetamol, mt-nac y mt-alcoholes de js/modules/libros/marino-toxicos.html. La pinta js/core/mayeutica.js.
// Datos puros. Formato: el de js/data/mayeutica/b1-fluidos.js. Cada pregunta enlaza su estado del hepatocito vivo
// (modelo: { hepatocitoVivo: '<estado>' }) y se comprueba en él después de contestar.
//
// Fuente: docs/marino-2024-toxicologia-caps52-53-apendices.pdf, págs. 3-8 (paracetamol y NAC) y 25-29 (alcoholes).
// Cada explicación y cada distractor dicen su página. Los pacientes (Casimira, Eufrasia, Nicanor, Gumersindo,
// Ruperto) se inventan; sus cifras de monitor son las que enseña el hepatocito vivo de la app. Cobertura:
// autonomo/bloques/b6b/cobertura-anexo.md §3 (6I) y §7. Las cuentas con el peso son ilustrativas (origen en cada una).

const TX = 'docs/marino-2024-toxicologia-caps52-53-apendices.pdf';
const pdf = (p, t = `PDF pág. ${p}`) => `<a class="biblio-link" href="${TX}#page=${p}" target="_blank" rel="noopener">${t}</a>`;
const H = estado => ({ hepatocitoVivo: estado });
// Test: `ok` es la buena, `malas` son [texto, qué le habría pasado al paciente]; `pos` la coloca (la app las baraja).
const T = (id, corto, fuente, enunciado, ok, malas, explicacion, pos = 0, extra = {}) => {
  const o = malas.map(([t, porque]) => ({ t, porque })); o.splice(pos, 0, { t: ok, ok: true });
  return { id, corto, tipo: 'test', fuente, enunciado, opciones: o, explicacion, ...extra };
};
const D = (id, corto, fuente, enunciado, puntos, explicacion, extra = {}) => ({ id, corto, tipo: 'destapa', fuente, enunciado, cuantas: puntos.length === 2 ? 'son dos cosas' : 'son tres cosas', puntos, explicacion, ...extra });
const E = (id, corto, fuente, enunciado, frases, explicacion, extra = {}) => ({ id, corto, tipo: 'error', fuente, enunciado, frases, explicacion, ...extra });
const mal = (t, c) => ({ t, mal: true, c });
const CUENTA = 'ilustrativo: cuenta sobre la pauta del libro';

